const MONTHS = {
  nb: ['januar', 'februar', 'mars', 'april', 'mai', 'juni', 'juli', 'august', 'september', 'oktober', 'november', 'desember'],
  en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
};
const MONTHS_SHORT = {
  nb: ['jan', 'feb', 'mar', 'apr', 'mai', 'jun', 'jul', 'aug', 'sep', 'okt', 'nov', 'des'],
  en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
};

/* Language: the browser's preferences decide (Norwegian bokmål/nynorsk -> nb, anything else -> en), unless the user picked one */
function detectLang() {
  const prefs = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']).map((l) => String(l).toLowerCase());
  for (const l of prefs) { if (/^(nb|nn|no)(-|$)/.test(l)) return 'nb'; if (/^en(-|$)/.test(l)) return 'en'; }
  return 'en';
}
let LANG = detectLang();
try { const s = localStorage.getItem('glett.lang'); if (s && I18N[s]) LANG = s; } catch (e) { /* ignore */ }

/* t('key', {var: value}) – falls back to English, then to the key itself */
function t(key, vars) {
  let s = (I18N[LANG] && I18N[LANG][key]) ?? I18N.en[key] ?? key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}
const hasT = (key) => !!(I18N[LANG] && I18N[LANG][key]) || !!I18N.en[key];
const monthName = (m, short = false) => (short ? MONTHS_SHORT : MONTHS)[LANG]?.[m - 1] || (short ? MONTHS_SHORT : MONTHS).en[m - 1];
const dateLocale = () => (LANG === 'nb' ? 'nb-NO' : 'en-GB');

/* Static texts in index.html: data-i18n (text), data-i18n-html, data-i18n-ph (placeholder), data-i18n-title */
function applyStaticI18n() {
  document.documentElement.lang = LANG;
  document.title = t('title');
  document.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); });
  document.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  document.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); el.setAttribute('aria-label', t(el.dataset.i18nTitle)); });
  document.querySelectorAll('[data-lang]').forEach((b) => b.classList.toggle('active', b.dataset.lang === LANG));
}

function setLang(lang) {
  if (!I18N[lang]) return;
  LANG = lang;
  try { localStorage.setItem('glett.lang', lang); } catch (e) { /* ignore */ }
  applyStaticI18n();
  if (typeof onLangChange === 'function') onLangChange();
}
